import zipfile, xml.etree.ElementTree as ET, openpyxl, pypdf, glob

def read_docx(p):
    print('=== DOCX:', p)
    with zipfile.ZipFile(p) as z:
        xml_content = z.read('word/document.xml')
    tree = ET.fromstring(xml_content)
    for elem in tree.iter():
        if elem.tag.endswith('}p'):
            texts = [t.text for t in elem.iter() if t.tag.endswith('}t') and t.text]
            if texts:
                print(''.join(texts))

def read_xlsx(p):
    print('=== XLSX:', p)
    wb = openpyxl.load_workbook(p, data_only=True)
    for name in wb.sheetnames:
        print('--- Sheet:', name)
        ws = wb[name]
        for row in ws.iter_rows(values_only=True):
            if any(row):
                print([str(c) if c is not None else '' for c in row])

def read_pdf(p):
    print('=== PDF:', p)
    reader = pypdf.PdfReader(p)
    for i, page in enumerate(reader.pages):
        print(f'--- Page {i+1} ---')
        print(page.extract_text())

for p in sorted(glob.glob('00_contract/*') + glob.glob('01_owner/*.docx') + glob.glob('01_owner/*.pdf')):
    if p.endswith('.docx'): read_docx(p)
    elif p.endswith('.xlsx'): read_xlsx(p)
    elif p.endswith('.pdf'): read_pdf(p)
