import re
from collections import Counter

with open('50_bim/BLDG4410-E_RevC.ifc') as f:
    lines = f.read().splitlines()

types = Counter()
for l in lines:
    m = re.match(r'^#(\d+)=([A-Z0-9_]+)\((.*)\);$', l)
    if m:
        types[m.group(2)] += 1
for k, v in sorted(types.items()):
    print(f'{k}: {v}')

print('--- Sample IFCLIGHTFIXTURE and FLOWSEGMENT / CABLECARRIER lines ---')
for i, l in enumerate(lines):
    if any(x in l for x in ['IFCLIGHTFIXTURE', 'IFCCABLECARRIER', 'IFCFLOWSEGMENT', 'IFCDISTRIBUTION', 'IFCSYSTEM', 'IFCGROUP']):
        for j in range(max(0, i-15), min(len(lines), i+15)):
            print(lines[j])
        break
