import xml.etree.ElementTree as ET
from collections import Counter

olgs = Counter()
for sec in ['26 05 73', '26 20 00', '26 24 13', '26 32 15', '26 36 23', '26 51 00']:
    p = f'20_guide_specifications/UFGS_Division_26_SpecsIntact/{sec}.SEC'
    with open(p, 'rb') as f: raw = f.read().decode('windows-1252')
    root = ET.fromstring(raw)
    for el in root.iter():
        if el.tag == 'OLG':
            olgs[tuple(c.tag for c in el)] += 1
        elif el.tag == 'OLI':
            for c in el:
                if c.tag in ('OLG', 'OLI'):
                    print('Nested in OLI:', sec, c.tag, c.attrib)
print('OLG children tags:', set(t for k in olgs for t in k))
